/**
 * Classifica um produto farmacêutico/varejo aplicando a Regra de Ouro (Blindagem de Medicamentos no Topo)
 * e palavras inteiras com `\b` (word boundary), sem jamais usar `.includes()` solto.
 */
export function classifyProductCategory(
  productName: string,
  brand?: string,
  _currentErpCategory?: string,
  activePrinciple?: string,
  description?: string,
  drugType?: string,
): CategoryClassificationResult {
  const nameNorm = normalizeForCategoryClassifier(productName);
  const brandNorm = normalizeForCategoryClassifier(brand);
  const activeNorm = normalizeForCategoryClassifier(activePrinciple);
  const drugTypeNorm = normalizeForCategoryClassifier(drugType);

  // Texto principal de decisão: Nome + Princípio Ativo + Marca (sem poluir com descrições longas ou categorias erradas antigas)
  const primaryWordText = `${nameNorm.wordText} ${activeNorm.wordText} ${brandNorm.wordText}`.trim();
  const nameAndActiveWordText = `${nameNorm.wordText} ${activeNorm.wordText}`.trim();

  // Detecta se há termos inequívocos de medicamento ou laboratório farmacêutico
  const hasMedicationFormOrDosage = MEDICATION_DOSAGE_AND_FORM_REGEX.test(nameAndActiveWordText);
  const hasMedicationActiveOrBrand = MEDICATION_ACTIVE_AND_BRAND_REGEX.test(nameAndActiveWordText);
  const isPharmaceuticalLab =
    PHARMA_LAB_REGEX.test(brandNorm.wordText) ||
    PHARMA_LAB_REGEX.test(nameNorm.wordText);
  const isPrescriptionOrGenericDrugType =
    /\b(?:GENERICO|SIMILAR|REFERENCIA|ETICO|CONTROLADO|ANTIBIOTICO|MEDICAMENTO)\b/.test(
      drugTypeNorm.wordText,
    );

  // =========================================================================
  // 1. PRIORIDADE 1: FRALDAS (Separar estritamente Adulto/Geriátrico vs. Infantil)
  // =========================================================================
  if (
    DIAPER_TRIGGER_REGEX.test(primaryWordText) &&
    !hasMedicationActiveOrBrand &&
    !/\b(?:CPR|COMPRIMIDO|COMPRIMIDOS|CAPS|CAPSULA|XAROPE|GTS|GOTAS|AMPOLA|INJETAVEL|COLIRIO)\b/.test(
      nameAndActiveWordText,
    )
  ) {
    if (ADULT_DIAPER_REGEX.test(primaryWordText)) {
      return {
        department: "Saúde, Ortopedia e Primeiros Socorros",
        category: "Cuidados Adulto / Geriátrico",
        subcategory: "Cuidados Adulto / Geriátrico",
        priority: 1,
      };
    }

    if (INFANT_DIAPER_REGEX.test(primaryWordText)) {
      return {
        department: "Mamãe e Bebê",
        category: "Fraldas Infantis",
        subcategory: "Fraldas Infantis",
        priority: 1,
      };
    }
  }

  // =========================================================================
  // 2. REGRA DE OURO: BLINDAGEM IMEDIATA DE MEDICAMENTOS EXPLÍCITOS (Princípios Ativos / Sais / Colírios)
  // =========================================================================
  // Se tiver princípio ativo/marca de medicamento (AAS, ALLEXOFEDRIN, ASSERT, SERTRALINA, BISMU-JET, ACU FRESH, FRESH TEARS, etc.)
  // ou sal farmacêutico / colírio / suspensão / xarope / gotas / injetável, vai IMEDIATAMENTE para Medicamentos!
  if (
    hasMedicationActiveOrBrand ||
    isPrescriptionOrGenericDrugType ||
    /\b(?:\d+(?:[.,]\d+)?\s*)?(?:DRG|DRAGEA|DRAGEAS|SUSP|SUSPENSAO|XPE|XAROPE|GTS|GOTAS|INJ|INJETAVEL|COLIRIO)\b|\b(?:SOLUCAO OFTALMICA|SOL OFTALMICA|LUBRIFICANTE OCULAR|FRESH TEARS|ACU FRESH|LACRIFILM|HYABAK|SYSTANE|OPTIVE|ECOFILM|CLORIDRATO|BROMIDRATO|MALEATO|BESILATO|SUCCINATO|TARTARATO|VALERATO|FUROATO|DIPROPIONATO|HEMITARTARATO|MESILATO|DICLORIDRATO|POMADA DERM|CREME DERM|GEL DERM|CREME VAGINAL|GEL VAGINAL|OVULO VAGINAL|SUPOSITORIO|ENEMA)\b/.test(
      nameAndActiveWordText,
    )
  ) {
    return classifyMedicationSubcategory(primaryWordText);
  }

  // =========================================================================
  // 3. EXCEÇÕES PERMITIDAS DENTRO DE LABORATÓRIOS (Vitaminas, Solar/Dermo, Higiene, Bebê, Primeiros Socorros)
  // =========================================================================

  // 3A. Mamãe e Bebê (Fórmulas, Mamadeiras, Chupetas, Lenços Umedecidos, Pomadas de Assadura)
  if (BABY_CARE_TRIGGER_REGEX.test(primaryWordText)) {
    if (BABY_FEEDING_REGEX.test(primaryWordText)) {
      return {
        department: "Mamãe e Bebê",
        category: "Alimentação Infantil",
        subcategory: "Alimentação Infantil",
        priority: 2,
      };
    }
    if (BABY_BREASTFEEDING_REGEX.test(primaryWordText)) {
      return {
        department: "Mamãe e Bebê",
        category: "Amamentação",
        subcategory: "Amamentação",
        priority: 2,
      };
    }
    return {
      department: "Mamãe e Bebê",
      category: "Higiene do Bebê",
      subcategory: "Higiene do Bebê",
      priority: 2,
    };
  }

  // 3B. Dermocosméticos e Proteção Solar
  if (DERMOCOSMETICS_AND_SOLAR_REGEX.test(primaryWordText)) {
    if (SOLAR_ONLY_REGEX.test(primaryWordText)) {
      return {
        department: "Dermocosméticos e Beleza",
        category: "Proteção Solar",
        subcategory: "Proteção Solar",
        priority: 3,
      };
    }
    return {
      department: "Dermocosméticos e Beleza",
      category: "Cuidados com o Rosto",
      subcategory: "Cuidados com o Rosto",
      priority: 3,
    };
  }

  // 3C. Cabelos, Unhas, Maquiagem, Perfumes e Corpo
  if (HAIR_AND_BEAUTY_TRIGGER_REGEX.test(primaryWordText)) {
    if (HAIR_ONLY_REGEX.test(primaryWordText)) {
      return {
        department: "Dermocosméticos e Beleza",
        category: "Cabelos",
        subcategory: "Cabelos",
        priority: 3,
      };
    }
    if (NAILS_ONLY_REGEX.test(primaryWordText)) {
      return {
        department: "Dermocosméticos e Beleza",
        category: "Cuidados com as Unhas",
        subcategory: "Cuidados com as Unhas",
        priority: 3,
      };
    }
    if (MAKEUP_ONLY_REGEX.test(primaryWordText)) {
      return {
        department: "Dermocosméticos e Beleza",
        category: "Maquiagem",
        subcategory: "Maquiagem",
        priority: 3,
      };
    }
    if (PERFUME_ONLY_REGEX.test(primaryWordText)) {
      return {
        department: "Dermocosméticos e Beleza",
        category: "Perfumes",
        subcategory: "Perfumes",
        priority: 3,
      };
    }
    return {
      department: "Dermocosméticos e Beleza",
      category: "Cuidados com o Corpo",
      subcategory: "Cuidados com o Corpo",
      priority: 3,
    };
  }

  // 3D. Higiene e Cuidados Pessoais (Bucal, Desodorantes, Sabonetes, Absorventes, Barba)
  if (PERSONAL_HYGIENE_TRIGGER_REGEX.test(primaryWordText)) {
    if (ORAL_HYGIENE_REGEX.test(primaryWordText)) {
      return {
        department: "Higiene e Cuidados Pessoais",
        category: "Higiene Bucal",
        subcategory: "Higiene Bucal",
        priority: 4,
      };
    }
    if (DEODORANT_REGEX.test(primaryWordText)) {
      return {
        department: "Higiene e Cuidados Pessoais",
        category: "Desodorantes",
        subcategory: "Desodorantes",
        priority: 4,
      };
    }
    if (FEMININE_ABSORBENT_REGEX.test(primaryWordText)) {
      return {
        department: "Higiene e Cuidados Pessoais",
        category: "Absorventes e Cuidados Femininos",
        subcategory: "Absorventes e Cuidados Femininos",
        priority: 4,
      };
    }
    if (INTIMATE_HYGIENE_REGEX.test(primaryWordText)) {
      return {
        department: "Higiene e Cuidados Pessoais",
        category: "Higiene Íntima",
        subcategory: "Higiene Íntima",
        priority: 4,
      };
    }
    if (SHAVING_MEN_REGEX.test(primaryWordText)) {
      return {
        department: "Higiene e Cuidados Pessoais",
        category: "Cuidados Masculinos",
        subcategory: "Cuidados Masculinos",
        priority: 4,
      };
    }
    if (COTTON_TISSUE_REGEX.test(primaryWordText)) {
      return {
        department: "Higiene e Cuidados Pessoais",
        category: "Lenços e Algodão",
        subcategory: "Lenços e Algodão",
        priority: 4,
      };
    }
    return {
      department: "Higiene e Cuidados Pessoais",
      category: "Banho e Corpo",
      subcategory: "Banho e Corpo",
      priority: 4,
    };
  }

  // 3E. Vitaminas e Suplementos
  if (VITAMINS_SUPPLEMENTS_TRIGGER_REGEX.test(primaryWordText)) {
    if (SPORTS_SUPPLEMENT_REGEX.test(primaryWordText)) {
      return {
        department: "Saúde e Bem-Estar",
        category: "Suplementos",
        subcategory: "Suplementos",
        priority: 5,
      };
    }
    if (SLEEP_SUPPLEMENT_REGEX.test(primaryWordText)) {
      return {
        department: "Saúde e Bem-Estar",
        category: "Sono e Relaxamento",
        subcategory: "Sono e Relaxamento",
        priority: 5,
      };
    }
    return {
      department: "Saúde e Bem-Estar",
      category: "Vitaminas e Suplementos",
      subcategory: "Vitaminas e Suplementos",
      priority: 5,
    };
  }

  // 3F. Primeiros Socorros, Curativos, Aparelhos e Ortopedia
  if (FIRST_AID_ORTHO_TRIGGER_REGEX.test(primaryWordText)) {
    if (ORTHO_ONLY_REGEX.test(primaryWordText)) {
      return {
        department: "Saúde, Ortopedia e Primeiros Socorros",
        category: "Ortopédicos",
        subcategory: "Ortopédicos",
        priority: 6,
      };
    }
    if (MEDICAL_DEVICES_REGEX.test(primaryWordText)) {
      return {
        department: "Saúde, Ortopedia e Primeiros Socorros",
        category: "Aparelhos de Saúde",
        subcategory: "Aparelhos de Saúde",
        priority: 6,
      };
    }
    return {
      department: "Saúde, Ortopedia e Primeiros Socorros",
      category: "Primeiros Socorros",
      subcategory: "Primeiros Socorros",
      priority: 6,
    };
  }

  // =========================================================================
  // 4. BLINDAGEM DE LABORATÓRIOS E DOSAGENS (MG, MCG, UI, CAPS, AMP)
  // =========================================================================
  // Se o produto pertence a um laboratório farmacêutico (EMS, HYPERA, MOMENTA, LEGRAND, GEOLAB, ALLERGAN, etc.)
  // ou possui MG/MCG/UI/CAPS/AMP, e não entrou nas exceções explícitas acima,
  // NUNCA pode cair em Conveniência / Snacks / Produtos para o Dia a Dia!
  if (isPharmaceuticalLab || hasMedicationFormOrDosage) {
    return classifyMedicationSubcategory(primaryWordText);
  }

  // =========================================================================
  // 5. CONVENIÊNCIA E SNACKS (Estritamente bloqueado para medicamentos/laboratórios)
  // =========================================================================
  if (STRICT_SNACKS_REGEX.test(nameNorm.wordText)) {
    return {
      department: "Conveniência",
      category: "Snacks",
      subcategory: "Snacks",
      priority: 7,
    };
  }

  if (STRICT_BEVERAGES_FOOD_REGEX.test(nameNorm.wordText)) {
    return {
      department: "Conveniência",
      category: "Alimentos e Bebidas",
      subcategory: "Alimentos e Bebidas",
      priority: 7,
    };
  }

  if (STRICT_CONVENIENCE_UTILITIES_REGEX.test(nameNorm.wordText)) {
    return {
      department: "Conveniência",
      category: "Utilidades",
      subcategory: "Utilidades",
      priority: 7,
    };
  }

  // =========================================================================
  // 6. FALLBACK SEGURO: MEDICAMENTOS (Com análise opcional da descrição/indicação apenas p/ subcategorias de medicamentos)
  // =========================================================================
  if (description) {
    const descNorm = normalizeForCategoryClassifier(description);
    const fullMedContext = `${primaryWordText} ${descNorm.wordText}`.trim();
    return classifyMedicationSubcategory(fullMedContext);
  }

  return classifyMedicationSubcategory(primaryWordText);
}
